1	package payflow
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"fmt"
7		"io"
8		"math/big"
9		"sort"
10	)
11	
12	// 离线流水对账：把外部支付渠道提供的有序流水与本地账本逐笔核对。
13	// 对账是只读操作，不改变余额、历史或账本文件。
14	//
15	// 逐条结果（保持输入顺序）有五种：
16	//   - matched：编号命中一条成功记录，且全部核对字段一致；
17	//   - field_mismatch：编号命中成功记录，但至少一个字段不同（逐个列出差异）；
18	//   - missing_in_ledger：账本中没有该编号的成功记录；
19	//   - duplicate：同一(kind,id)在输入中出现多次，整组全部标为重复并附全部
20	//     输入位置，不再判断字段差异，也不再把对应账本记录列为缺失；
21	//   - out_of_scope：命中同类型同编号的成功记录，但该记录的成功序号不在本次
22	//     核对范围内（after < seq <= through）。不比较字段、不计入流水侧汇总；
23	//     该编号在流水中出现多次时全部按此状态处理（优先于整组重复）。
24	//
25	// 付款编号与退款编号分别匹配，同名也不会混为一笔。只核对成功记录：
26	// 已退款的付款仍按原扣款核对，退款单独核对。账本中没有任何对应流水的入选
27	// 记录另列缺失（先按付款成功顺序，再按退款成功顺序）。范围只影响记录是否
28	// 参加核对，不切断关联：入选退款仍可指向范围外付款，入选付款仍携带范围外
29	// 退款的信息。
30	
31	const (
32		ReconMatched         = "matched"
33		ReconFieldMismatch   = "field_mismatch"
34		ReconMissingInLedger = "missing_in_ledger"
35		ReconDuplicate       = "duplicate"
36		ReconOutOfScope      = "out_of_scope"
37	)
38	
39	// amountJSON 是必须提供、且为 int64 整数的金额。
40	// 使用指针 + 自定义解码区分“缺省/null/非数字/越界”等情形。
41	type amountJSON struct {
42		v int64
43	}
44	
45	func (a *amountJSON) UnmarshalJSON(data []byte) error {
46		if string(data) == "null" {
47			return fmt.Errorf("amount must be an int64 integer, not null")
48		}
49		dec := json.NewDecoder(bytes.NewReader(data))
50		var v int64
51		if err := dec.Decode(&v); err != nil {
52			return err
53		}
54		// 单个数字字面量必须恰好结束。
55		if tok, err := dec.Token(); err != io.EOF {
56			if err == nil {
57				return fmt.Errorf("invalid integer amount (unexpected token %v)", tok)
58			}
59			return err
60		}
61		a.v = v
62		return nil
63	}
64	
65	// flowEntryJSON 是流水的严格解码形态。未知字段按标准库惯例忽略。
66	type flowEntryJSON struct {
67		Kind         string      `json:"kind"`
68		ID           string      `json:"id"`
69		Account      string      `json:"account"`
70		Asset        string      `json:"asset"`
71		Amount       *amountJSON `json:"amount"`
72		Fee          *amountJSON `json:"fee"`
73		Charged      *amountJSON `json:"charged"`
74		SettlementID string      `json:"settlement_id"`
75	}
76	
77	// flowRequestJSON 是对账输入：{"entries":[...]}。
78	type flowRequestJSON struct {
79		Entries []flowEntryJSON `json:"entries"`
80	}
81	
82	// FlowEntry 是校验通过后的一条流水。Index 是从 0 开始的输入位置。
83	type FlowEntry struct {
84		Index        int
85		Kind         string
86		ID           string
87		Account      string
88		Asset        string
89		Amount       int64
90		Fee          int64
91		Charged      int64
92		SettlementID string // 仅退款有意义
93	}
94	
95	// FieldDiff 是一个不同字段：账本值与流水值逐字并列。
96	type FieldDiff struct {
97		Field  string `json:"field"`
98		Ledger string `json:"ledger"`
99		Flow   string `json:"flow"`
100	}
101	
102	// ReconRecordRef 指向一条账本成功记录，并携带其关联记录（付款被退时的退款
103	// 编号、退款的原付款编号），使每个能定位到账本的结果都可追溯。
104	type ReconRecordRef struct {
105		Kind         string `json:"kind"`
106		ID           string `json:"id"`
107		Account      string `json:"account"`
108		Asset        string `json:"asset"`
109		Amount       int64  `json:"amount"`
110		Fee          int64  `json:"fee"`
111		Charged      int64  `json:"charged"`
112		Seq          int64  `json:"seq"`
113		SettlementID string `json:"settlement_id,omitempty"` // 退款记录：原付款编号
114		RefundID     string `json:"refund_id,omitempty"`     // 结算已被退款时：退款编号
115		RefundSeq    int64  `json:"refund_seq,omitempty"`
116	}
117	
118	// ReconResult 是一条输入流水的核对结果，顺序与输入一致。
119	type ReconResult struct {
120		Index     int             `json:"index"`
121		Kind      string          `json:"kind"`
122		ID        string          `json:"id"`
123		Status    string          `json:"status"`
124		Positions []int           `json:"positions,omitempty"` // duplicate：整组全部输入位置
125		Diffs     []FieldDiff     `json:"diffs,omitempty"`
126		Record    *ReconRecordRef `json:"record,omitempty"` // 命中账本记录时带上，可追溯关联结算/退款
127	}
128	
129	// ReconTotalRow 是一个 (账户, 资产) 组合单侧的金额汇总。金额使用十进制整数
130	// 字符串，累计可超过 int64 仍保持精确；不同资产各自一行，不相加、不抵消。
131	type ReconTotalRow struct {
132		Account       string `json:"account"`
133		Asset         string `json:"asset"`
134		ChargedTotal  string `json:"charged_total"`
135		RefundedTotal string `json:"refunded_total"`
136		NetCharged    string `json:"net_charged"`
137	}
138	
139	// ReconNetDiff 是一个组合的净扣款差额，方向为流水减账本。
140	type ReconNetDiff struct {
141		Account          string `json:"account"`
142		Asset            string `json:"asset"`
143		LedgerNetCharged string `json:"ledger_net_charged"`
144		FlowNetCharged   string `json:"flow_net_charged"`
145		NetChargedDiff   string `json:"net_charged_diff"`
146	}
147	
148	// ReconTotals 是账本侧与流水侧各自的汇总。
149	type ReconTotals struct {
150		Ledger []ReconTotalRow `json:"ledger"`
151		Flow   []ReconTotalRow `json:"flow"`
152	}
153	
154	// ReconReport 是一次对账的完整报告。
155	type ReconReport struct {
156		Results         []ReconResult    `json:"results"`
157		MissingPayments []ReconRecordRef `json:"missing_payments"`
158		MissingRefunds  []ReconRecordRef `json:"missing_refunds"`
159		Totals          ReconTotals      `json:"totals"`
160		NetDiff         []ReconNetDiff   `json:"net_diff"`
161		MaxPaymentSeq   int64            `json:"max_payment_seq"`
162		MaxRefundSeq    int64            `json:"max_refund_seq"`
163		PaymentAfter    int64            `json:"payment_after"`
164		PaymentThrough  int64            `json:"payment_through"`
165		RefundAfter     int64            `json:"refund_after"`
166		RefundThrough   int64            `json:"refund_through"`
167	}
168	
169	// ReconcileBounds 限定付款与退款各自的核对范围：每类记录只核对成功序号
170	// 满足 after < seq <= through 的记录（下界排除、上界包含）。两类记录各用
171	// 自己的序号，分别选择范围，不根据退款引用的付款序号判断退款是否入选。
172	//
173	// 指针为 nil 表示该侧不限制：下界缺省取 0，上界缺省取本次所见该类记录的
174	// 最大成功序号（即完整历史）。显式给出的上下界必须是非负 int64，且
175	// after <= through、through 不超过对应类别的最大成功序号；after == through
176	// 表示范围为空（该类记录全部不参加核对）。
177	type ReconcileBounds struct {
178		PaymentAfter   *int64
179		PaymentThrough *int64
180		RefundAfter    *int64
181		RefundThrough  *int64
182	}
183	
184	// validateFlowEntry 校验一条流水的语义约束（JSON 解析与 Go 直接调用共用，
185	// 保证两种提交方式对相同内容给出一致判断）：kind 只能是 payment/refund；
186	// 编号、账户、资产不能为空；amount、charged 必须为正，fee 必须非负；
187	// refund 还必须带非空 settlement_id。i 是该条目在传入列表中的位置。
188	//
189	// 注意这里只校验输入本身：amount+fee 是否等于 charged、退款引用的原付款
190	// 是否与账本一致属于核对结论（field_mismatch），不是参数错误。
191	func validateFlowEntry(i int, e FlowEntry) error {
192		at := func(msg string) error {
193			return ledgerError(ErrInvalid, "reconcile entry %d: %s", i, msg)
194		}
195		if e.Kind != "payment" && e.Kind != "refund" {
196			return at(fmt.Sprintf("unknown kind %q (want payment or refund)", e.Kind))
197		}
198		if e.ID == "" {
199			return at("id must not be empty")
200		}
201		if e.Account == "" {
202			return at("account must not be empty")
203		}
204		if e.Asset == "" {
205			return at("asset must not be empty")
206		}
207		if e.Amount <= 0 {
208			return at("amount must be a positive int64")
209		}
210		if e.Fee < 0 {
211			return at("fee must be a non-negative int64")
212		}
213		if e.Charged <= 0 {
214			return at("charged must be a positive int64")
215		}
216		if e.Kind == "refund" && e.SettlementID == "" {
217			return at("settlement_id must not be empty for a refund")
218		}
219		return nil
220	}
221	
222	// ParseReconcileRequest 严格解析对账输入。
223	// 字段缺失、类型不符、未知 kind、数值越界或非法 JSON 均返回 invalid_parameter；
224	// 任一条目不合法则整次拒绝，不产生部分结果。
225	func ParseReconcileRequest(raw []byte) ([]FlowEntry, error) {
226		dec := json.NewDecoder(bytes.NewReader(raw))
227		var req flowRequestJSON
228		if err := dec.Decode(&req); err != nil {
229			return nil, ledgerError(ErrInvalid, "parse reconcile JSON: %v", err)
230		}
231		if tok, err := dec.Token(); err != io.EOF {
232			if err == nil {
233				return nil, ledgerError(ErrInvalid, "reconcile: unexpected trailing content after JSON document (token %v)", tok)
234			}
235			return nil, ledgerError(ErrInvalid, "reconcile: %v", err)
236		}
237		// entries 必须显式提供；{} 等缺省列表的文档视为非法输入，
238		// 只有 {"entries":[]} 才表示“空列表：全部账本记录缺失”。
239		if req.Entries == nil {
240			return nil, ledgerError(ErrInvalid, "reconcile: entries is required")
241		}
242	
243		entries := make([]FlowEntry, 0, len(req.Entries))
244		for i, e := range req.Entries {
245			// 结构性约束（字段必须提供且为 int64）只存在于 JSON 入口。
246			if e.Amount == nil {
247				return nil, ledgerError(ErrInvalid, "reconcile entry %d: amount is required and must be an int64 integer", i)
248			}
249			if e.Fee == nil {
250				return nil, ledgerError(ErrInvalid, "reconcile entry %d: fee is required and must be an int64 integer", i)
251			}
252			if e.Charged == nil {
253				return nil, ledgerError(ErrInvalid, "reconcile entry %d: charged is required and must be an int64 integer", i)
254			}
255			entry := FlowEntry{
256				Index:        i,
257				Kind:         e.Kind,
258				ID:           e.ID,
259				Account:      e.Account,
260				Asset:        e.Asset,
261				Amount:       e.Amount.v,
262				Fee:          e.Fee.v,
263				Charged:      e.Charged.v,
264				SettlementID: e.SettlementID,
265			}
266			// 语义约束与 Go 入口共用同一套校验，报错信息也保持一致。
267			if err := validateFlowEntry(i, entry); err != nil {
268				return nil, err
269			}
270			entries = append(entries, entry)
271		}
272		return entries, nil
273	}
274	
275	// reconSide 累计单侧（账本或流水）的金额。流水侧可能包含账本外的组合，
276	// 且累计允许超过 int64，因此一律用大整数。
277	type reconSide struct {
278		charged  map[balanceKey]*big.Int
279		refunded map[balanceKey]*big.Int
280	}
281	
282	func newReconSide() reconSide {
283		return reconSide{charged: map[balanceKey]*big.Int{}, refunded: map[balanceKey]*big.Int{}}
284	}
285	
286	// add 把一条流水或账本记录计入对应合计：payment 计入扣款，refund 计入退款。
287	// 两类记录共用同一套累计逻辑，差别只在目标合集。
288	func (s *reconSide) add(kind string, k balanceKey, v int64) {
289		m := s.charged
290		if kind == "refund" {
291			m = s.refunded
292		}
293		x := m[k]
294		if x == nil {
295			x = new(big.Int)
296			m[k] = x
297		}
298		x.Add(x, big.NewInt(v))
299	}
300	
301	// reconLane 汇集一类流水（付款或退款）参与逐条核对所需的全部账本视图与
302	// 判定状态。付款与退款的逐条流程（范围外 → 整组重复 → 唯一核对）完全相同，
303	// 差异只在匹配对象、关联信息与核对字段，全部收敛到各自的 lane：
304	//   - records/byID：按成功顺序的记录引用（付款携带其退款编号，退款携带原
305	//     付款编号），编号索引按类各自独立，同名编号也不会混为一笔；
306	//   - inRange：该类记录自己的序号范围判断；
307	//   - seen/covered/missing：输入位置统计、入选记录覆盖情况与缺失列表。
308	type reconLane struct {
309		kind    string
310		inRange func(seq int64) bool
311		records []ReconRecordRef           // 按成功顺序排列
312		byID    map[string]*ReconRecordRef // 指向 records 中的元素
313		seen    map[string][]int           // 编号 → 全部输入位置
314		covered map[string]bool            // 唯一出现且命中入选记录的编号（含字段不符）
315		missing []ReconRecordRef           // 入选但流水未覆盖的记录，按成功顺序
316	}
317	
318	func newReconLane(kind string, inRange func(seq int64) bool) *reconLane {
319		return &reconLane{
320			kind:    kind,
321			inRange: inRange,
322			byID:    map[string]*ReconRecordRef{},
323			seen:    map[string][]int{},
324			covered: map[string]bool{},
325			missing: []ReconRecordRef{},
326		}
327	}
328	
329	// index 在 records 全部就位后建立编号索引（元素地址在追加完成后才稳定）。
330	func (l *reconLane) index() {
331		for i := range l.records {
332			l.byID[l.records[i].ID] = &l.records[i]
333		}
334	}
335	
336	// attach 把命中记录（含关联信息）的独立副本挂到结果上。
337	func attachRef(rec *ReconRecordRef) *ReconRecordRef {
338		cp := *rec
339		return &cp
340	}
341	
342	// ReconcileFlow 对一批外部流水与当前账本状态做只读对账，核对范围为完整
343	// 历史（付款与退款都取各自全部成功记录）。等价于 ReconcileFlowRanged 传入
344	// 空边界。
345	//
346	// entries 与命令行 {"entries":[...]} 适用同一套输入检查：kind 只能是
347	// payment/refund，编号/账户/资产非空，amount、charged 为正，fee 非负，
348	// refund 必须带 settlement_id。任一条目不合法即返回 invalid_parameter
349	// （报告为 nil，不产生部分结果），Go 调用者无需先把条目转成 JSON 解析。
350	// nil 或空列表表示没有外部流水，正常列出核对范围内的账本缺失记录。
351	func (l *Ledger) ReconcileFlow(entries []FlowEntry) (*ReconReport, error) {
352		return l.ReconcileFlowRanged(entries, ReconcileBounds{})
353	}
354	
355	// resolveReconRange 确定一类记录的实际核对边界 (after, through]，并校验：
356	// 边界必须非负、after 不大于 through、through 不超过该类最大成功序号。
357	// 空历史的最大序号为零，因此缺省边界为 (0,0]，范围为空。
358	func resolveReconRange(kind string, after, through *int64, maxSeq int64) (int64, int64, error) {
359		a := int64(0)
360		if after != nil {
361			a = *after
362		}
363		t := maxSeq
364		if through != nil {
365			t = *through
366		}
367		if a < 0 {
368			return 0, 0, ledgerError(ErrInvalid, "reconcile %s bounds: after must be a non-negative int64, got %d", kind, a)
369		}
370		if t < 0 {
371			return 0, 0, ledgerError(ErrInvalid, "reconcile %s bounds: through must be a non-negative int64, got %d", kind, t)
372		}
373		if a > t {
374			return 0, 0, ledgerError(ErrInvalid, "reconcile %s bounds: after %d must not exceed through %d", kind, a, t)
375		}
376		if t > maxSeq {
377			return 0, 0, ledgerError(ErrInvalid, "reconcile %s bounds: through %d exceeds max seq %d", kind, t, maxSeq)
378		}
379		return a, t, nil
380	}
381	
382	// ReconcileFlowRanged 对一批外部流水与当前账本状态做只读对账，只核对成功
383	// 序号落在边界内的记录（after < seq <= through）。边界不改变账本状态，
384	// 整份报告仍在同一把账本互斥锁内生成，对应同一个完整账本状态。
385	//
386	// 范围只影响记录是否参加核对，不切断关联：入选退款仍可指向范围外付款，
387	// 入选付款仍携带范围外退款的信息。命中同类型同编号但记录在范围外的流水
388	// 返回 out_of_scope（携带账本记录、不比较字段、不计入流水侧汇总）；该编号
389	// 在流水中出现多次时全部按 out_of_scope 处理。
390	func (l *Ledger) ReconcileFlowRanged(entries []FlowEntry, bounds ReconcileBounds) (*ReconReport, error) {
391		if err := l.beginOp(); err != nil {
392			return nil, err
393		}
394		defer l.endOp()
395	
396		// 与命令行入口相同的输入检查：按传入列表顺序找到第一条非法流水即整次
397		// 拒绝（invalid_parameter），报告为空、不产生部分汇总，也不触碰账本。
398		// 位置用列表下标而非调用者给出的 Index；校验只读、不改写传入条目。
399		for i := range entries {
400			if err := validateFlowEntry(i, entries[i]); err != nil {
401				return nil, err
402			}
403		}
404	
405		l.reg.mu.Lock()
406		defer l.reg.mu.Unlock()
407	
408		st := l.stateView()
409	
410		maxPay := int64(len(st.Settlements))
411		maxRef := int64(len(st.Refunds))
412		payAfter, payThrough, err := resolveReconRange("payment", bounds.PaymentAfter, bounds.PaymentThrough, maxPay)
413		if err != nil {
414			return nil, err
415		}
416		refAfter, refThrough, err := resolveReconRange("refund", bounds.RefundAfter, bounds.RefundThrough, maxRef)
417		if err != nil {
418			return nil, err
419		}
420		inPayRange := func(seq int64) bool { return seq > payAfter && seq <= payThrough }
421		inRefRange := func(seq int64) bool { return seq > refAfter && seq <= refThrough }
422	
423		// 结算编号 / 退款编号各自索引：同名编号也不会混为一笔。
424		// 关联索引始终基于完整历史：范围不切断付款与退款之间的关联，
425		// 入选退款仍可指向范围外付款，入选付款仍携带范围外退款的信息。
426		refundOfPay := make(map[string]*RefundRecord, len(st.Refunds))
427		for i := range st.Refunds {
428			refundOfPay[st.Refunds[i].SettlementID] = &st.Refunds[i]
429		}
430		payLane := newReconLane("payment", inPayRange)
431		for i := range st.Settlements {
432			r := &st.Settlements[i]
433			payLane.records = append(payLane.records, paymentRef(r, refundOfPay[r.ID]))
434		}
435		payLane.index()
436		refundLane := newReconLane("refund", inRefRange)
437		for i := range st.Refunds {
438			refundLane.records = append(refundLane.records, refundRef(&st.Refunds[i]))
439		}
440		refundLane.index()
441		// lanes 的顺序即缺失报告与账本侧合计的处理顺序：先付款后退款。
442		lanes := []*reconLane{payLane, refundLane}
443		laneOf := map[string]*reconLane{"payment": payLane, "refund": refundLane}
444	
445		// 统计每个 (kind,id) 在输入中出现的全部位置：出现多次则整组重复，
446		// 无论内容是否相同。
447		for i := range entries {
448			e := &entries[i]
449			lane := laneOf[e.Kind]
450			lane.seen[e.ID] = append(lane.seen[e.ID], e.Index)
451		}
452	
453		report := &ReconReport{
454			Results:        make([]ReconResult, 0, len(entries)),
455			NetDiff:        []ReconNetDiff{},
456			MaxPaymentSeq:  maxPay,
457			MaxRefundSeq:   maxRef,
458			PaymentAfter:   payAfter,
459			PaymentThrough: payThrough,
460			RefundAfter:    refAfter,
461			RefundThrough:  refThrough,
462		}
463	
464		ledgerSide := newReconSide()
465		flowSide := newReconSide()
466	
467		// 逐条结果（保持输入顺序）。两类流水共用同一条核对流水线，
468		// 类别差异（匹配对象、关联引用、合计方向、核对字段）由 lane 提供。
469		for i := range entries {
470			e := &entries[i]
471			lane := laneOf[e.Kind]
472			res := ReconResult{Index: e.Index, Kind: e.Kind, ID: e.ID}
473			k := balanceKey{e.Account, e.Asset}
474			rec := lane.byID[e.ID]
475	
476			// 1. 命中同类型同编号但记录在范围外：不比较字段、不计入流水侧汇总；
477			//    该编号在流水中出现多次时全部按 out_of_scope 处理（优先于整组重复）。
478			if rec != nil && !lane.inRange(rec.Seq) {
479				res.Status = ReconOutOfScope
480				res.Record = attachRef(rec)
481				report.Results = append(report.Results, res)
482				continue
483			}
484	
485			// 2. 记录在范围内或账本无此编号：保留整组重复判定，流水侧合计仍包含
486			//    每一条（范围内重复项与账本外流水逐条计入）。
487			if positions := lane.seen[e.ID]; len(positions) > 1 {
488				res.Status = ReconDuplicate
489				res.Positions = append([]int(nil), positions...)
490				flowSide.add(lane.kind, k, e.Charged)
491				if rec != nil {
492					res.Record = attachRef(rec)
493				}
494				report.Results = append(report.Results, res)
495				continue
496			}
497	
498			// 3. 唯一条目：命中入选记录则逐字段核对，否则账本缺这笔。
499			flowSide.add(lane.kind, k, e.Charged)
500			if rec != nil {
501				lane.covered[e.ID] = true
502				res.Record = attachRef(rec)
503				if diffs := compareFields(lane.kind, rec, e); len(diffs) > 0 {
504					res.Status = ReconFieldMismatch
505					res.Diffs = diffs
506				} else {
507					res.Status = ReconMatched
508				}
509			} else {
510				res.Status = ReconMissingInLedger
511			}
512			report.Results = append(report.Results, res)
513		}
514	
515		// 账本侧合计只包含入选记录：已退款的付款仍按原扣款计入，退款单独计入
516		// 退款侧；只选退款时扣款合计为零，不会顺带计入原付款。
517		for _, lane := range lanes {
518			for i := range lane.records {
519				r := &lane.records[i]
520				if lane.inRange(r.Seq) {
521					ledgerSide.add(lane.kind, balanceKey{r.Account, r.Asset}, r.Charged)
522				}
523			}
524		}
525	
526		// 入选但流水未覆盖的成功记录另列缺失（先付款后退款，各按成功顺序）。
527		// 唯一出现即算覆盖（含字段不符）；重复组对应记录按规则不列为缺失；
528		// 范围外记录不列入缺失。
529		for _, lane := range lanes {
530			for i := range lane.records {
531				r := &lane.records[i]
532				if !lane.inRange(r.Seq) {
533					continue
534				}
535				if lane.covered[r.ID] {
536					continue
537				}
538				if len(lane.seen[r.ID]) > 1 {
539					continue
540				}
541				lane.missing = append(lane.missing, *r)
542			}
543		}
544		report.MissingPayments = payLane.missing
545		report.MissingRefunds = refundLane.missing
546	
547		report.Totals = ReconTotals{
548			Ledger: buildTotalRows(ledgerSide),
549			Flow:   buildTotalRows(flowSide),
550		}
551		report.NetDiff = buildNetDiff(ledgerSide, flowSide)
552		return report, nil
553	}
554	
555	// compareFields 逐字段核对流水与命中的账本记录：账户、资产、amount、fee、
556	// charged 五个字段两类流水共用；退款额外核对原付款编号 settlement_id。
557	// 每个不同字段都保留账本值与流水值。
558	func compareFields(kind string, r *ReconRecordRef, e *FlowEntry) []FieldDiff {
559		var diffs []FieldDiff
560		addStr := func(field, ledger, flow string) {
561			if ledger != flow {
562				diffs = append(diffs, FieldDiff{Field: field, Ledger: ledger, Flow: flow})
563			}
564		}
565		addInt := func(field string, ledger, flow int64) {
566			if ledger != flow {
567				diffs = append(diffs, FieldDiff{Field: field, Ledger: fmt.Sprintf("%d", ledger), Flow: fmt.Sprintf("%d", flow)})
568			}
569		}
570		addStr("account", r.Account, e.Account)
571		addStr("asset", r.Asset, e.Asset)
572		addInt("amount", r.Amount, e.Amount)
573		addInt("fee", r.Fee, e.Fee)
574		addInt("charged", r.Charged, e.Charged)
575		if kind == "refund" {
576			addStr("settlement_id", r.SettlementID, e.SettlementID)
577		}
578		return diffs
579	}
580	
581	func paymentRef(r *Record, rf *RefundRecord) ReconRecordRef {
582		ref := ReconRecordRef{
583			Kind:    "payment",
584			ID:      r.ID,
585			Account: r.Account,
586			Asset:   r.Asset,
587			Amount:  r.Amount,
588			Fee:     r.Fee,
589			Charged: r.Charged,
590			Seq:     r.Seq,
591		}
592		if rf != nil {
593			ref.RefundID = rf.ID
594			ref.RefundSeq = rf.Seq
595		}
596		return ref
597	}
598	
599	func refundRef(r *RefundRecord) ReconRecordRef {
600		return ReconRecordRef{
601			Kind:         "refund",
602			ID:           r.ID,
603			Account:      r.Account,
604			Asset:        r.Asset,
605			Amount:       r.Amount,
606			Fee:          r.Fee,
607			Charged:      r.Charged,
608			Seq:          r.Seq,
609			SettlementID: r.SettlementID,
610		}
611	}
612	
613	// sideNet 返回某组合的净扣款（扣款 - 退款）。
614	func sideNet(side reconSide, k balanceKey) *big.Int {
615		charged := new(big.Int)
616		if x := side.charged[k]; x != nil {
617			charged.Set(x)
618		}
619		refunded := new(big.Int)
620		if x := side.refunded[k]; x != nil {
621			refunded.Set(x)
622		}
623		return charged.Sub(charged, refunded)
624	}
625	
626	func allKeys(a, b reconSide) []balanceKey {
627		seen := map[balanceKey]bool{}
628		var keys []balanceKey
629		add := func(m map[balanceKey]*big.Int) {
630			for k := range m {
631				if !seen[k] {
632					seen[k] = true
633					keys = append(keys, k)
634				}
635			}
636		}
637		add(a.charged)
638		add(a.refunded)
639		add(b.charged)
640		add(b.refunded)
641		sort.Slice(keys, func(i, j int) bool {
642			if keys[i].account != keys[j].account {
643				return keys[i].account < keys[j].account
644			}
645			return keys[i].asset < keys[j].asset
646		})
647		return keys
648	}
649	
650	// buildTotalRows 按账户、资产排序输出单侧汇总；净扣款 = 扣款 - 退款。
651	func buildTotalRows(side reconSide) []ReconTotalRow {
652		keys := allKeys(side, reconSide{})
653		out := make([]ReconTotalRow, 0, len(keys))
654		for _, k := range keys {
655			charged := new(big.Int)
656			if x := side.charged[k]; x != nil {
657				charged.Set(x)
658			}
659			refunded := new(big.Int)
660			if x := side.refunded[k]; x != nil {
661				refunded.Set(x)
662			}
663			net := new(big.Int).Sub(new(big.Int).Set(charged), refunded)
664			out = append(out, ReconTotalRow{
665				Account:       k.account,
666				Asset:         k.asset,
667				ChargedTotal:  charged.String(),
668				RefundedTotal: refunded.String(),
669				NetCharged:    net.String(),
670			})
671		}
672		return out
673	}
674	
675	// buildNetDiff 输出每个（任一侧出现过的）组合的净扣款差额，方向为流水减账本。
676	func buildNetDiff(ledger, flow reconSide) []ReconNetDiff {
677		out := make([]ReconNetDiff, 0)
678		for _, k := range allKeys(ledger, flow) {
679			lNet := sideNet(ledger, k)
680			fNet := sideNet(flow, k)
681			diff := new(big.Int).Sub(new(big.Int).Set(fNet), lNet)
682			out = append(out, ReconNetDiff{
683				Account:          k.account,
684				Asset:            k.asset,
685				LedgerNetCharged: lNet.String(),
686				FlowNetCharged:   fNet.String(),
687				NetChargedDiff:   diff.String(),
688			})
689		}
690		return out
691	}
692

