// r2（退 p2）。账本扣款合计 2006、退款合计 2006、净扣款 0。
func regNetZeroLedger(t *testing.T) (*Ledger, string) {
	t.Helper()
	path := newTestLedger(t, []BalanceInit{
		{Account: "aa-1", Asset: "usdc", Balance: math.MaxInt64},
	})
